_elementor_page_settings.custom_css:
/* cores e fontes da Rede Turística para o blog padrão (24/09/2026) */
:root{
  --blog-fundo:#FFFFFF;
  --blog-fundo-2:#F4F4F4;
  --blog-texto:#3C3D3D;
  --blog-texto-suave:#666666;
  --blog-titulo:#3C3D3D;
  --blog-acento:#E98300;
  --blog-acento-texto:#C56F00;
  --blog-fio:#E6E6E6;
  --blog-display:"Montserrat","Segoe UI",sans-serif;
  --blog-ui:"Roboto","Segoe UI",sans-serif;
  --blog-nav-h:0px;
  --blog-pad:max(16px,calc((100vw - 1140px) / 2));
  --blog-ease:cubic-bezier(.22,.61,.36,1);
  --blog-foto-filtro:none;
  --blog-capa-fundo:#3C3D3D;
  --blog-capa-filtro:brightness(.9);
  --blog-capa-scrim:linear-gradient(to top,rgba(0,0,0,.85) 0%,rgba(0,0,0,.45) 42%,rgba(0,0,0,.15) 74%,rgba(0,0,0,.45) 100%);
  --blog-capa-texto:#FFFFFF;
  --blog-capa-texto-suave:rgba(255,255,255,.75);
}
.blog-head .eyebrow{font-family:var(--blog-ui);font-size:12px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;margin:0}
.blog-head-in{max-width:calc(760px + var(--blog-pad))}
.blog-head{background:var(--blog-fundo);color:var(--blog-texto);padding:0}
.blog-head-in{padding:calc(var(--blog-nav-h) + clamp(52px,7vw,96px)) var(--blog-pad) clamp(34px,4.5vw,56px);max-width:760px}
.blog-head h1{font-family:var(--blog-display);font-weight:400;font-size:clamp(34px,5vw,58px);line-height:1.08;color:var(--blog-titulo);margin:20px 0 16px}
.blog-head-in > p:not(.eyebrow){color:var(--blog-texto-suave);max-width:52ch;font-size:16.5px;line-height:1.6;margin:0}
.blog-head .eyebrow,.blog-cta .eyebrow{color:var(--blog-acento-texto)}
.blog-head-in{padding-left:var(--blog-pad)!important;padding-right:var(--blog-pad)!important;max-width:calc(760px + var(--blog-pad))}
@media (max-width:767px){.blog-head-in{padding-top:40px}}
.blog-head{background:transparent}
/* card do formulário */
.rt-cot-card{border-radius:10px;box-shadow:0 10px 40px rgba(0,0,0,.07)}
.rt-cot .jet-form-builder h2.wp-block-heading{font-family:Montserrat,sans-serif;font-size:24px;font-weight:600;color:#3C3D3D;margin:0 0 20px}
.rt-cot .jet-form-builder h4.wp-block-heading{font-family:Montserrat,sans-serif;font-size:17px!important;font-weight:600;color:#E98300;margin:36px 0 16px;padding-top:28px;border-top:1px solid #EEEEEE;text-transform:uppercase;letter-spacing:.06em}
.rt-cot .jet-form-builder-row{margin-bottom:18px}
.rt-cot .jet-form-builder__label-text{font-family:Roboto,sans-serif;font-size:15px;font-weight:500;color:#3C3D3D}
.rt-cot .jet-form-builder__required{color:#E98300}
.rt-cot .jet-form-builder__desc{font-size:13px;color:#8A8A8A;margin-top:6px}
.rt-cot .jet-form-builder__field.text-field,.rt-cot .jet-form-builder__field.select-field,.rt-cot .jet-form-builder__field.date-field,.rt-cot .jet-form-builder__field.textarea-field{width:100%;min-height:50px;padding:12px 14px;border:1px solid #D9D9D9;border-radius:8px;background:#FFFFFF;font-size:15px;color:#3C3D3D;box-shadow:none;transition:border-color .2s,box-shadow .2s}
.rt-cot .jet-form-builder__field.textarea-field{min-height:120px}
.rt-cot .jet-form-builder__field:focus{border-color:#E98300;box-shadow:0 0 0 3px rgba(233,131,0,.15);outline:0}
.rt-cot .checkradio-wrap .jet-form-builder__field-label{display:inline-flex;align-items:center;gap:10px;padding:6px 0;font-size:15px;color:#3C3D3D;cursor:pointer}
.rt-cot .radio-field{accent-color:#E98300;width:18px;height:18px}
.rt-cot .jet-form-builder__fields-group.checkradio-wrap{display:flex;flex-wrap:wrap;gap:4px 28px}
.rt-cot .jet-form-builder__submit{width:100%;margin-top:12px;padding:18px 32px;border:0;border-radius:8px;background:#E98300;color:#FFFFFF;font-family:Montserrat,sans-serif;font-size:16px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;transition:background .25s,transform .25s}
.rt-cot .jet-form-builder__submit:hover{background:#3C3D3D;transform:translateY(-2px)}

.rt-cot .jet-form-builder__field.email-field,.rt-cot .jet-form-builder__field.tel-field{width:100%;min-height:50px;padding:12px 14px;border:1px solid #D9D9D9;border-radius:8px;background:#FFFFFF;font-size:15px;color:#3C3D3D}
.rt-cot input,.rt-cot textarea{font-family:inherit}
.rt-cot form input[type=text],.rt-cot form input[type=email],.rt-cot form input[type=tel],.rt-cot form textarea{width:100%;min-height:50px;padding:12px 14px;border:1px solid #D9D9D9;border-radius:8px;background:#FFFFFF;font-size:15px;color:#3C3D3D;box-shadow:none;transition:border-color .2s,box-shadow .2s}
.rt-cot form textarea{min-height:140px}
.rt-cot form input:focus,.rt-cot form textarea:focus{border-color:#E98300;box-shadow:0 0 0 3px rgba(233,131,0,.15);outline:0}
.rt-cot form button[type=submit]{width:100%;margin-top:8px;padding:18px 32px;border:0;border-radius:8px;background:#E98300;color:#FFFFFF;font-family:Montserrat,sans-serif;font-size:16px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;transition:background .25s,transform .25s}
.rt-cot form button[type=submit]:hover{background:#3C3D3D;transform:translateY(-2px)}
.rt-form-intro .eyebrow{font-family:Roboto,sans-serif;font-size:12px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;color:#C56F00;margin:0}
.rt-form-intro h2{font-family:Montserrat,sans-serif;font-size:28px;font-weight:300;color:#3C3D3D;margin:12px 0 8px}
.rt-form-intro p:last-child{color:#777;margin:0 0 24px}
/* canais */
.rt-canais{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
@media (max-width:1024px){.rt-canais{grid-template-columns:repeat(2,1fr)}}
@media (max-width:560px){.rt-canais{grid-template-columns:1fr}}
.rt-canal{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:6px;text-align:left;background:#FFFFFF;border:0;border-radius:10px;padding:28px 26px;box-shadow:0 10px 40px rgba(0,0,0,.06);color:#3C3D3D;text-decoration:none;cursor:pointer;overflow:hidden;font:inherit;transition:transform .4s cubic-bezier(.22,.61,.36,1),box-shadow .4s}
.rt-canal::before{content:"";position:absolute;top:0;left:0;right:0;height:4px;background:#E98300;transform:scaleX(0);transform-origin:0 50%;transition:transform .5s cubic-bezier(.22,.61,.36,1)}
.rt-canal:hover{transform:translateY(-6px);box-shadow:0 18px 44px rgba(0,0,0,.12);color:#3C3D3D;background:#FFFFFF}
.rt-canal:hover::before{transform:scaleX(1)}
.rt-canal-ic{width:52px;height:52px;border-radius:50%;background:#FFF1E0;color:#E98300;display:flex;align-items:center;justify-content:center;margin-bottom:10px;transition:background .3s,color .3s}
.rt-canal-ic svg{width:26px;height:26px}
.rt-canal:hover .rt-canal-ic{background:#E98300;color:#FFFFFF}
.rt-canal--zap .rt-canal-ic{background:#E7F9EE;color:#1DA851}
.rt-canal--zap:hover .rt-canal-ic{background:#25D366;color:#FFFFFF}
.rt-canal strong{font-family:Montserrat,sans-serif;font-size:18px;font-weight:600}
.rt-canal-dado{font-size:15px;color:#666;word-break:break-word}
.rt-canal-cta{margin-top:10px;font-family:Roboto,sans-serif;font-size:12px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:#C56F00}
/* onde estamos */
.rt-onde{height:100%;background:#FFFFFF;border-radius:10px;padding:34px 30px;box-shadow:0 10px 40px rgba(0,0,0,.05);display:flex;flex-direction:column}
.rt-onde h3{font-family:Montserrat,sans-serif;font-size:22px;font-weight:600;color:#3C3D3D;margin:0 0 10px}
.rt-onde>p{color:#666;margin:0 0 18px;line-height:1.6}
.rt-mapa{flex:1;min-height:280px;border-radius:8px;overflow:hidden;background:#EEE}
.rt-mapa iframe{display:block;width:100%;height:100%;min-height:280px;border:0;filter:grayscale(.35)}
.rt-rota{display:inline-block;margin:16px 0 22px;font-family:Roboto,sans-serif;font-size:12px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;color:#C56F00;text-decoration:none}
.rt-rota:hover{color:#E98300}
.rt-horario{display:flex;justify-content:space-between;gap:12px;border-top:1px solid #EEE;padding-top:18px;font-size:15px;color:#666}
.rt-horario strong{color:#3C3D3D}
.elementor-widget-html:has(.rt-canais),.elementor-widget-html:has(.rt-onde){width:100%}
.elementor-widget-html:has(.rt-onde){height:100%}
